INSERT INTO cms_site_settings (id, config, revision) VALUES (1, '{"org":"LOS SANTOS FIRE DEPARTMENT","sub":"PUBLIC INFORMATION OFFICE","sections":[{"id":"press","label":"Press Releases","kind":"sec"},{"id":"incident","label":"Incident Reports","kind":"sec"},{"id":"divs","label":"Divisions","kind":"divs"},{"id":"advisory","label":"Safety Advisories","kind":"sec"},{"id":"bulletin","label":"Public Bulletins","kind":"sec"}],"divisions":["Arson Counter Terrorism","EMS","HAZMAT","Fire Suppression"],"dispatch":{"title":"LSFD LIVE DISPATCH STATUS","active":"3","units":"42","response":"4:12","alert":"Red Flag advisory – Blueberry / Red County","phone":"Emergency: 9-1-1"},"listTitle":"Recent Press Releases","disclaimer":"This release is issued by the Los Santos Fire Department Public Information Office. Information is accurate at the time of publication and may be updated as investigations develop. For emergencies, dial 9-1-1. © 2026 Los Santos City Fire Department – Founded 1886. All rights reserved.","footer":"© 2026 Los Santos City Fire Department – Public Information Office. Founded 1886. In an emergency, call 9-1-1. This portal is the official source of LSFD press information."}'::jsonb, 0);
