INSERT INTO cms_posts (id, data) VALUES
('s1', '{"id":"s1","type":"incident","tag":"Arson Investigation","division":"Arson Counter Terrorism","status":"Under Investigation","title":"Arson investigation underway in El Corona after suspected deliberate fire","author":"PIO Captain, LSFD Public Relations","date":"2026-10-10T23:10","image":"/assets/default-hero.jpg","content":"EL CORONA, Los Santos – Fire investigators are examining a suspected arson at a residence on Unity Boulevard after evidence suggested the fire may have been deliberately set. The Los Santos Fire Department''s Arson Counter Terrorism Section is leading the investigation.\n\nInvestigators deployed a specialized K-9 unit trained to detect accelerants. According to field reports, the canine detected traces consistent with gasoline inside the damaged building. A used jerrycan believed to have been used to spread fuel was also recovered.\n\n\"All physical evidence at the scene points to one conclusion: this was not an accident, but a planned act,\" said Arson Fire Captain Adam Garpen. Debris samples and the suspected fuel container have been sent for forensic testing to identify potential fingerprints or DNA evidence.\n\nThe department urges anyone who witnessed suspicious activity near Unity Boulevard on the night of the incident to contact authorities through the 9-1-1 emergency hotline. Informant identities will remain confidential."}'::jsonb),
('s2', '{"id":"s2","type":"advisory","tag":"Public Safety","division":"Fire Suppression","status":"Active Advisory","title":"Brush fire season: LSFD issues Red Flag guidance for Blueberry and Red County","author":"PIO Lieutenant, LSFD Public Relations","date":"2026-10-09T09:30","image":"","content":"LOS SANTOS – With dry conditions and seasonal winds forecast through the week, the Los Santos Fire Department has issued a Red Flag advisory for Blueberry and Red County.\n\nResidents are asked to avoid open flames, refrain from using power equipment on dry vegetation, and maintain at least 30 feet of defensible space around structures.\n\nAny sign of smoke or fire should be reported immediately to 9-1-1. Do not attempt to fight a wildland fire yourself."}'::jsonb),
('s3', '{"id":"s3","type":"press","tag":"Public Health","division":"EMS","status":"Community","title":"LSFD EMS opens free CPR and AED training sessions across the city","author":"PIO Captain, LSFD Public Relations","date":"2026-10-08T14:00","image":"","content":"LOS SANTOS – The LSFD Emergency Medical Services Division will host free hands-only CPR and AED training sessions at city fire stations beginning next week.\n\nCertified paramedics will guide participants through recognizing cardiac arrest, performing compressions, and operating automated external defibrillators. No registration is required and sessions are open to all residents aged 12 and older.\n\n\"Bystander action in the first minutes saves lives,\" the division said in a statement."}'::jsonb),
('s4', '{"id":"s4","type":"incident","tag":"Structure Fire","division":"Fire Suppression","status":"Resolved","title":"Two-alarm structure fire at Davis warehouse contained, no injuries reported","author":"PIO Lieutenant, LSFD Public Relations","date":"2026-10-07T03:45","image":"","content":"DAVIS, Los Santos – Firefighters contained a two-alarm fire at a commercial warehouse in Davis early Wednesday. Crews arrived within minutes and mounted an aggressive interior and exterior attack.\n\nNo civilians or firefighters were injured. The cause is under investigation and the building has been turned over to the property owner."}'::jsonb),
('s5', '{"id":"s5","type":"bulletin","tag":"Hazardous Materials","division":"HAZMAT","status":"Closed","title":"HAZMAT team neutralizes chemical leak at Terminal Island facility","author":"PIO Captain, LSFD Public Relations","date":"2026-10-05T18:20","image":"","content":"TERMINAL ISLAND, Los Santos – The LSFD HAZMAT Division responded to a reported chemical leak at an industrial facility. Nearby streets were briefly closed as a precaution.\n\nThe substance was contained and neutralized. Air monitoring showed no ongoing risk to the public, and all roads have reopened."}'::jsonb);
